ObjectStates.LuaScript:
function onLoad()

    self.setName("发牌")
    self.setDescription("推进到下一个发牌阶段")
    self.lock()

    bParam = {}
    bParam.click_function = 'playGame'
    bParam.function_owner = Global
    bParam.label = '发牌'
    bParam.tooltip = '为所有已入座玩家发两张底牌'
    bParam.position = {0,0.23,0}
    bParam.rotation = {0,180,0}
    bParam.width = 5000
    bParam.height = 3000
    bParam.font_size = 10000
    bParam.color = {111/255, 255/255, 125/255}
    self.createButton(bParam)
end

function emptyFunction()
end

function playGame(objectButtonClicked, playerColorClicked)
    Global.call("playGame", {objectButtonClicked, playerColorClicked})
end

